async function requireSensitiveMfa(req,actor=null){actor||=await activeUser(req);const policy=await configValue("security",{mfa_policy:"optional",step_up_for_sensitive_actions:false}),roles=actor.roles||[],required=policy.mfa_policy==="staff_required"&&roles.some(role=>role!=="user")||policy.mfa_policy==="admin_required"&&roles.some(role=>role!=="user"&&role!=="moderator");if(policy.step_up_for_sensitive_actions&&required&&jwtPayload((req.headers.authorization||"").replace(/^Bearer /,"")).aal!=="aal2")throw Object.assign(new Error(`Recent multi-factor authentication is required by the ${policy.mfa_policy.replaceAll("_"," ")} policy`),{status:403,code:"mfa_required",policy:policy.mfa_policy})}
