async function suspensionContext(targetId){
  const [profiles,assignments]=await Promise.all([
    supabase(`/rest/v1/profiles?id=eq.${targetId}&select=id,display_name,first_name,last_name,suspended_until`),
    supabase(`/rest/v1/user_roles?user_id=eq.${targetId}&select=role_key`)
  ]);
  if(!profiles.length)throw Object.assign(new Error("User not found"),{status:404});
  const roles=assignments.map(item=>item.role_key);
  return{profile:profiles[0],roles};
}
async function assertSuperAdminContinuity(targetId,targetRoles){
  if(!targetRoles.includes("super_admin"))return;
  const assignments=await supabase("/rest/v1/user_roles?role_key=eq.super_admin&select=user_id");
  const ids=[...new Set(assignments.map(item=>item.user_id))];
  if(!ids.length)return;
  const profiles=await supabase(`/rest/v1/profiles?id=in.(${ids.join(",")})&select=id,suspended_until`);
  const active=profiles.filter(profile=>!profile.suspended_until||new Date(profile.suspended_until)<=new Date());
  if(active.length<=1&&active.some(profile=>profile.id===targetId))throw Object.assign(new Error("The final active super administrator cannot be suspended"),{status:409});
}

const species = new Set(["mallard", "teal", "gadwall", "pintail", "wood_duck", "diver", "mixed", "other", "canada_goose", "snow_goose", "white_fronted_goose", "sandhill_crane", "tundra_swan"]);
const behaviors = new Set(["feeding", "circling", "flying_over", "resting", "moving_in"]);

function validateSighting(input,maxAgeDays=7) {
  const latitude = Number(input.latitude);
  const longitude = Number(input.longitude);
  const occurredAt = new Date(input.occurred_at||Date.now());
  const locationSource=["current","map","saved","popular","search"].includes(input.location_source)?input.location_source:"current";
  if (!behaviors.has(input.behavior)) throw Object.assign(new Error("Invalid sighting details"), { status: 400 });
  if (!Number.isFinite(latitude) || latitude < -90 || latitude > 90 || !Number.isFinite(longitude) || longitude < -180 || longitude > 180) throw Object.assign(new Error("Invalid coordinates"), { status: 400 });
  if(Number.isNaN(occurredAt.getTime()))throw Object.assign(new Error("A valid observation time is required"),{status:400});
  if(occurredAt.getTime()>Date.now()+5*60000)throw Object.assign(new Error("Observation time cannot be in the future"),{status:400});
  if(occurredAt.getTime()<Date.now()-Math.max(1,Number(maxAgeDays)||7)*86400000)throw Object.assign(new Error(`Reports must be submitted within ${maxAgeDays} days of the observation`),{status:400});
  return { latitude, longitude,occurredAt,locationSource };
}

const preferenceGroups = ["ducks", "geese", "cranes", "doves", "shorebirds", "upland", "other"];
const defaultPreferences = { visible_groups: preferenceGroups, default_days: 30, start_view: "us", auto_open_card: true, appearance: "system", map_view: "density", reduced_map_motion: false, colorblind_map: false };
function validatePreferences(input = {}) {
  const groups = Array.isArray(input.visible_groups) ? input.visible_groups.filter(v => preferenceGroups.includes(v)) : defaultPreferences.visible_groups;
  return {
    visible_groups: [...new Set(groups)],
    default_days: [1, 7, 30, 90, 180, 365].includes(Number(input.default_days)) ? Number(input.default_days) : 30,
    start_view: ["us", "world", "my_area"].includes(input.start_view) ? input.start_view : "us",
    auto_open_card: input.auto_open_card !== false,
    appearance: ["system", "dark", "light"].includes(input.appearance) ? input.appearance : "system",
    map_view: "density",
    reduced_map_motion: input.reduced_map_motion === true,
    colorblind_map: input.colorblind_map === true,
  };
}

async function moderationContext(row,full=false){
  let content=null,sightingId=row.content_type==="sighting"||row.content_type==="note"?row.content_id:null,ownerId=null;
  if(row.content_type==="comment"){const rows=await supabase(`/rest/v1/sighting_comments?id=eq.${row.content_id}&select=id,sighting_id,commenter_id,body,created_at`);content=rows[0]||null;sightingId=content?.sighting_id;ownerId=content?.commenter_id}
  if(row.content_type==="photo"){const rows=await supabase(`/rest/v1/sighting_media?id=eq.${row.content_id}&select=id,sighting_id,uploader_id,mime_type,byte_size,created_at`);content=rows[0]||null;sightingId=content?.sighting_id;ownerId=content?.uploader_id}
  const sightings=sightingId?await supabase(`/rest/v1/sightings?id=eq.${sightingId}&select=id,reporter_id,species_slug,flock_size,behavior,notes,confidence,occurred_at,submitted_at,location_source,created_at,status`):[];const baseSighting=sightings[0]||null,delayMinutes=baseSighting?Math.max(0,Math.round((new Date(baseSighting.submitted_at||baseSighting.created_at)-new Date(baseSighting.occurred_at))/60000)):0,submissionContext=baseSighting?`Submission context: ${String(baseSighting.location_source||"current").replaceAll("_"," ")} location · ${delayMinutes<60?`${delayMinutes} minute`:delayMinutes<1440?`${Math.round(delayMinutes/60)} hour`:`${Math.round(delayMinutes/1440)} day`}${delayMinutes===1?"":"s"} after observation`:null;const sighting=baseSighting?{...baseSighting,submission_delay_minutes:delayMinutes,submission_context:submissionContext,notes:[baseSighting.notes,submissionContext].filter(Boolean).join("\n\n")}:null;ownerId=ownerId||sighting?.reporter_id;
  const profiles=ownerId?await supabase(`/rest/v1/profiles?id=eq.${ownerId}&select=id,display_name,first_name,last_name,role,trust_score,report_count,suspended_until`):[];const owner=profiles[0]||null;
  const reports=await supabase(`/rest/v1/content_reports?content_type=eq.${row.content_type}&content_id=eq.${row.content_id}&select=id,reporter_id,reason,details,created_at&order=created_at.desc&limit=50`);
  if(!full)return{...row,content_preview:content?.body?.slice(0,180)||sighting?.notes?.slice(0,180)||null,sighting,owner,report_count:reports.length};
  const reporterIds=[...new Set(reports.map(item=>item.reporter_id).filter(Boolean))],reporterProfiles=reporterIds.length?await supabase(`/rest/v1/profiles?id=in.(${reporterIds.join(",")})&select=id,display_name,first_name,last_name`):[],reporterNames=new Map(reporterProfiles.map(item=>[item.id,item.display_name||[item.first_name,item.last_name].filter(Boolean).join(" ")||"FeatherMap member"]));
  const [comments,media,history,duplicates]=sightingId?await Promise.all([supabase(`/rest/v1/sighting_comments?sighting_id=eq.${sightingId}&select=id,commenter_id,body,created_at&order=created_at.asc&limit=100`),supabase(`/rest/v1/sighting_media?sighting_id=eq.${sightingId}&select=id,uploader_id,mime_type,byte_size,created_at&order=created_at.asc`),supabase(`/rest/v1/admin_audit_log?target_id=eq.${row.content_id}&select=id,actor_id,action,details,created_at&order=created_at.desc&limit=50`),supabase(`/rest/v1/duplicate_candidates?or=(sighting_a.eq.${sightingId},sighting_b.eq.${sightingId})&select=*&order=created_at.desc&limit=20`)]):[[],[],[],[]];
  return{...row,content,sighting,owner,reports:reports.map(item=>({...item,reported_by:reporterNames.get(item.reporter_id)||"FeatherMap member"})),comments,media:media.map(item=>({...item,url:`/api/media/${item.id}`})),history,duplicates};
}

